SELECT s1."c0" AS "ts", s1."c1" AS "later", s1."c2" AS "scaled" FROM (SELECT s2."c2" AS "c0", s2."c3" AS "c1", s2."c4" AS "c2" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c0" AS "c2", DATEADD(MICROSECOND, 60000000, s3."c0") AS "c3", ((s3."c1" * CAST('2.5' AS FLOAT)) + CAST('0.0' AS FLOAT)) AS "c4" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1" FROM (SELECT "ts" AS "c0", ("value" + CAST('0.0' AS FLOAT)) AS "c1" FROM "readings") AS s4 WHERE COALESCE((((NOT (s4."c1" = CAST('-9999.0' AS FLOAT))) AND (NOT ((NOT (s4."c1" IS NULL)) AND (s4."c1" = CAST('NaN' AS FLOAT))))) AND (CAST('0.5' AS FLOAT) < s4."c1")), FALSE)) AS s3) AS s2) AS s1
